export default async function next(
  { activities, page, previousState, acknowledgeActivityId, resolution },
  context,
) {
  const saved = (await context.state.get("strava-social")) ?? { initialized: false, ids: [] };
  if (!Array.isArray(saved.ids)) throw Error("Invalid activity state");
  if (saved.pending) {
    if (acknowledgeActivityId !== saved.pending || !["confirmed", "retry"].includes(resolution))
      throw Error("Inspect X and resolve pending activity " + saved.pending);
    if (resolution === "confirmed" && !saved.ids.includes(saved.pending))
      saved.ids.push(saved.pending);
    saved.pending = null;
    await context.state.set("strava-social", saved);
  }
  if (!Array.isArray(activities)) throw Error("Missing Strava activities");
  const index = previousState?.page === page ? previousState.index : 0;
  if (!Number.isInteger(index) || index < 0 || index > activities.length)
    throw Error("Invalid page index");
  if (index === activities.length) {
    const hasNext = activities.length === 200;
    if (!hasNext && !saved.initialized) {
      saved.initialized = true;
      await context.state.set("strava-social", saved);
    }
    return {
      state: { page, index },
      more: false,
      process: false,
      hasNext,
      nextPage: page + 1,
      id: "",
      text: "",
    };
  }
  if (!saved.initialized) {
    for (const activity of activities) {
      const id = String(activity.id ?? "");
      if (!id || !Number.isSafeInteger(Number(id))) throw Error("Invalid activity ID");
      if (!saved.ids.includes(id)) saved.ids.push(id);
    }
    await context.state.set("strava-social", saved);
    return {
      state: { page, index: activities.length },
      more: true,
      process: false,
      hasNext: false,
      nextPage: page + 1,
      id: "",
      text: "",
    };
  }
  let nextIndex = index;
  while (
    nextIndex < activities.length &&
    saved.ids.includes(String(activities[nextIndex].id ?? ""))
  )
    nextIndex++;
  if (nextIndex === activities.length)
    return {
      state: { page, index: nextIndex },
      more: true,
      process: false,
      hasNext: false,
      nextPage: page + 1,
      id: "",
      text: "",
    };
  const activity = activities[nextIndex],
    id = String(activity.id ?? "");
  if (!id || !Number.isSafeInteger(Number(id))) throw Error("Invalid activity ID");
  const state = { page, index: nextIndex + 1 };
  if (typeof activity.name !== "string" || typeof activity.distance !== "number")
    throw Error("Activity missing name or distance");
  return {
    state,
    more: true,
    process: true,
    hasNext: false,
    nextPage: page + 1,
    id,
    text: `I ran ${activity.distance} meters and completed my ${activity.name}!`,
  };
}

