export default async function reserve({ id }, context) {
  const state = await context.state.get("strava-social");
  if (!state || !Array.isArray(state.ids) || state.pending) throw Error("Resolve pending activity");
  state.pending = id;
  await context.state.set("strava-social", state);
  return { id };
}

