export default async function confirm({ id }, context) {
  const state = await context.state.get("strava-social");
  if (!state || state.pending !== id) throw Error("Pending activity mismatch");
  if (!state.ids.includes(id)) state.ids.push(id);
  state.pending = null;
  await context.state.set("strava-social", state);
  return { done: true };
}
